INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Frame-Aufbau dasselbe wie ein Netzwerkprotokoll?', 2, '[{"text": "No", "correct": true, "because": "Struktur vs. Regeln"}, {"text": "Yes", "correct": false, "because": "Different concepts"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of a frame structure?', 3, '[{"text": "Organize data for network transmission", "correct": true, "because": "Data encapsulation"}, {"text": "Encrypt data", "correct": false, "because": "Not primary"}, {"text": "Store data permanently", "correct": false, "because": "Not storage-related"}]'),
('00000000-0000-0000-0000-000000000000', 'Which components are part of an Ethernet frame?', 5, '[{"text": "Preamble", "correct": true, "because": "Synchronization"}, {"text": "Destination MAC", "correct": true, "because": "Target address"}, {"text": "Paper header", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) An Ethernet frame includes a CRC field. b) It’s only for wireless networks.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Wired focus"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore in a frame structure?', 4, '[{"text": "Header fields", "correct": false, "because": "Essential"}, {"text": "Payload", "correct": false, "because": "Data content"}, {"text": "Paper size", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if every frame includes a preamble?', 2, '[{"text": "Yes", "correct": true, "because": "Synchronization"}, {"text": "No", "correct": false, "because": "Ethernet standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Which field in an Ethernet frame checks data integrity?', 3, '[{"text": "CRC", "correct": true, "because": "Cyclic Redundancy Check"}, {"text": "Preamble", "correct": false, "because": "Synchronization"}, {"text": "EtherType", "correct": false, "because": "Protocol type"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does a frame structure provide?', 5, '[{"text": "Error detection", "correct": true, "because": "CRC"}, {"text": "Addressing", "correct": true, "because": "MAC addresses"}, {"text": "High-speed printing", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) Frames include source and destination MAC addresses. b) They’re only for Layer 3. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Layer 2 focus"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need in a frame structure?', 4, '[{"text": "MAC addresses", "correct": false, "because": "Addressing"}, {"text": "Payload", "correct": false, "because": "Data transport"}, {"text": "Paper documentation", "correct": true, "because": "Digital sufficient"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does every Ethernet frame include an EtherType field?', 2, '[{"text": "Yes", "correct": true, "because": "Protocol identification"}, {"text": "No", "correct": false, "because": "Standard component"}]'),
('00000000-0000-0000-0000-000000000000', 'Which layers use the frame structure?', 4, '[{"text": "Data Link Layer", "correct": true, "because": "Layer 2"}, {"text": "Physical Layer", "correct": true, "because": "Layer 1 transmission"}, {"text": "Application Layer", "correct": false, "because": "Layer 7"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that frames don’t include error checking. Is that true?', 2, '[{"text": "No", "correct": true, "because": "CRC included"}, {"text": "Yes", "correct": false, "because": "Error detection present"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize in a frame structure?', 3, '[{"text": "Data integrity", "correct": true, "because": "CRC ensures"}, {"text": "Font style", "correct": false, "because": "Irrelevant"}, {"text": "Speed alone", "correct": false, "because": "Integrity key"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Frames have a preamble for synchronization. b) They’re only for wireless networks.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Ethernet is wired"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What fields are critical in an Ethernet frame?', 5, '[{"text": "Source MAC", "correct": true, "because": "Sender address"}, {"text": "FCS", "correct": true, "because": "Frame Check Sequence"}, {"text": "Print format", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for a frame structure?', 3, '[{"text": "Payload", "correct": false, "because": "Data content"}, {"text": "MAC addresses", "correct": false, "because": "Addressing"}, {"text": "Paper records", "correct": true, "because": "No impact"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does a frame include a field for protocol identification?', 3, '[{"text": "Yes", "correct": true, "because": "EtherType"}, {"text": "No", "correct": false, "because": "Part of structure"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if frames vary in size?', 2, '[{"text": "Yes", "correct": true, "because": "64-1518 bytes"}, {"text": "No", "correct": false, "because": "Size range exists"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to a frame structure?', 4, '[{"text": "Data encapsulation", "correct": true, "because": "Core principle"}, {"text": "Physical storage", "correct": false, "because": "Not storage"}, {"text": "Font size", "correct": false, "because": "Irrelevant"}]');
